entries[279944] = { ["name"] = "Sharpening Wheel", ["text"] = "Requires Blacksmithing (20)\n\nUse: Constructs a sharpening wheel that grants you and others sitting nearby [6][11][20][34] increased Strength, mutually exclusive with Strength of Earth Totem.\n\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279945] = { ["name"] = "Sewing Machine", ["text"] = "Requires Leatherworking (300)\n\nUse: Places a Sewing Machine usable for recipes that require it, and provides all of the benefits of a Camp Tent. Requires a Campfire nearby.\n\nMay be placed over a Camp Tent to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279947] = { ["name"] = "Seed Hybridizer", ["text"] = "Requires Herbalism (300)\n\nUse: Places a Seed Hybridizer that allows seeds to be multiplied or combined into rarer tiers, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\nMay be placed over an Incense Candle to replace it.\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279948] = { ["name"] = "Rock Garden", ["text"] = "Requires Mining (140)\n\nUse: Places a Rock Garden that spawns a common mining node over time, and provides all the benefits of a Lodestone. Requires a Campfire nearby.\n\nMay be placed over a Lodestone to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279949] = { ["name"] = "Repair Bot", ["text"] = "Requires Engineering (140)\n\nUse: Summons a Repair Bot that allows you and others nearby to buy reagents and repair gear. Requires a Campfire nearby.\n\nMay be placed over a Reagent Bot to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279950] = { ["name"] = "Reagent Bot", ["text"] = "Requires Engineering (20)\n\nUse: Summons a Reagent Bot that allows you and others nearby to purchase reagents. Requires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
