entries[279960] = { ["name"] = "Lodestone", ["text"] = "Requires Mining (20)\n\nUse: Erects a lodestone that allows you and others sitting nearby to gain [12][20][32][49][67][90] increased melee Attack Power, mutually exclusive with Blessing of Might.\n\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279961] = { ["name"] = "Journeyman Campfire Kit", ["text"] = "Requires Cooking (140)\n\nUse: Builds a journeyman campfire that allows cooking and the placement of up to 5 additional camp features. Players sitting or crafting nearby for 1 min will gain benefits from other camp features. (5 Min Cooldown)" }
entries[279962] = { ["name"] = "Incense Candle", ["text"] = "Requires Herbalism (20)\n\nUse: Ignites an incense candle that allows you and others sitting nearby to gain [2][6][12][18][25] increased Intellect, mutually exclusive with Arcane Intellect.\n\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279964] = { ["name"] = "Greenhouse", ["text"] = "Requires Herbalism (140)\n\nUse: Places a Greenhouse that will grow herbs over time from seeds planted, and provides all of the benefits of an Incense Candle. Requires a Campfire nearby.\n\nMay be placed over an Incense Candle to replace it.\nAll camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
entries[279965] = { ["name"] = "Fishing Rack", ["text"] = "Requires Fishing (140)\n\nUse: Places a Fishing Rack that grants the ability to catch uncommon fish for 1 hour, provides Fishing Skill lures, and provides all of the benefits of a Fish Bowl. Requires a Campfire nearby.\n\nMay be placed over a Fish Bowl to replace it. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
