entries[279967] = { ["name"] = "Fish Bowl", ["text"] = "Requires Fishing (20)\n\nUse: Places a small fish bowl that allows you and others sitting nearby to gain 8% increased stats, mutually exclusive with Blessing of Kings.\n\nRequires a Campfire nearby. All camping features share a cooldown of 1 hour. (1 Hour Cooldown)" }
